function expand({ assets, rows, ...census }: ChainCensus) {
  return {
    ...census,
    vaults: rows.map(
      (r): IporFusionVault => ({
        address: r[0],
        index: r[1],
        version: r[2],
        createdBlock: r[3],
        createdTx: r[4],
        name: r[5],
        symbol: r[6],
        shareDecimals: r[7],
        asset: { address: assets[r[8]][0], symbol: assets[r[8]][1], decimals: assets[r[8]][2] },
        initialOwner: r[9],
        plasmaVaultBase: r[10],
        feeManager: r[11],
        totalAssets: r[12],
        isFusionVault: r[13],
      }),
    ),
  };
}

/** Per chain: the census block, the factory, and the vault roster in index order. A FLOOR — see the header. */
export const IPOR_FUSION_CENSUS = {
  ethereum: expand(CENSUS.ethereum),
  arbitrum: expand(CENSUS.arbitrum),
  base: expand(CENSUS.base),
};
